import React from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import KaabaModel from './KaabaModel';
import MaqamIbrahimModel from './MaqamIbrahimModel';
import PilgrimsModel from './PilgrimsModel';
import WebGLBoundary from '../common/WebGLBoundary';

// The flat Kaaba shown where the 3D one can't run (no WebGL).
export const KaabaIcon = ({ size = 64 }) => (
    <svg width={size} height={size} viewBox="0 0 64 64" role="img" aria-label="Kaaba">
        {/* top */}
        <path d="M32 10 L54 21 L32 32 L10 21 Z" fill="#2b2b2b" />
        {/* left face */}
        <path d="M10 21 L32 32 L32 56 L10 45 Z" fill="#111" />
        {/* right face */}
        <path d="M54 21 L32 32 L32 56 L54 45 Z" fill="#1c1c1c" />
        {/* gold band (kiswah) */}
        <path d="M10 26 L32 37 L32 41 L10 30 Z" fill="#D4AF37" />
        <path d="M54 26 L32 37 L32 41 L54 30 Z" fill="#C9A227" />
        {/* door */}
        <path d="M38 41 L44 38 L44 46 L38 49 Z" fill="#D4AF37" />
    </svg>
);

const Kaaba3D = () => (
    <WebGLBoundary fallback={<KaabaIcon size={40} />}>
        <Canvas camera={{ position: [5, 5, 5], fov: 50 }} style={{ width: 64, height: 64 }}>
            <ambientLight intensity={0.7} />
            <directionalLight position={[10, 10, 5]} intensity={1} />
            <KaabaModel />
            <MaqamIbrahimModel />
            <PilgrimsModel />
            <OrbitControls enableZoom={false} />
        </Canvas>
    </WebGLBoundary>
);

export default Kaaba3D;
